// Package sep provides server endpoint types and middleware for streaming RPC
package sep

import (
	"context"

	"github.com/cloudwego/kitex/pkg/streaming"
)

// StreamEndpoint represents a server-side streaming endpoint that handles bidirectional streaming
// It receives a ServerStream from the request and returns a modified ServerStream in the response
type StreamEndpoint func(ctx context.Context, stream streaming.ServerStream) (streaming.ServerStream, error)

// StreamMiddleware wraps a StreamEndpoint to add additional behavior
type StreamMiddleware func(next StreamEndpoint) StreamEndpoint

// StreamMiddlewareBuilder builds a StreamMiddleware with information from a context
type StreamMiddlewareBuilder func(ctx context.Context) StreamMiddleware

// StreamChain connects multiple stream middlewares into one (applied right-to-left)
func StreamChain(mws ...StreamMiddleware) StreamMiddleware {
	return func(next StreamEndpoint) StreamEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

