func apacheUnmarshal(trans bufiox.Reader, data interface{}) error {
	// Try to use faster codecs (FastCodec or Frugal) before falling back to Apache
	tc := getTypeCodec(data)

	// Attempt FastCodec fallback if available
	if tc.FastCodec {
		// Skip and capture the struct bytes to get dataLen
		buf, err := skipThriftStruct(trans)
		if err == nil {
			// Try fast unmarshal with the captured buffer length
			reader := bufiox.NewBytesReader(buf)
			if fastErr := fastUnmarshal(reader, data, len(buf)); fastErr == nil {
				return nil
			}
			// Fast unmarshal failed, reset reader for next attempt
			trans = bufiox.NewBytesReader(buf)
		}
	}

	// Attempt Frugal fallback if available
	if tc.Frugal {
		// Skip and capture the struct bytes to get dataLen
		buf, err := skipThriftStruct(trans)
		if err == nil {
			// Try frugal unmarshal with the captured buffer length
			reader := bufiox.NewBytesReader(buf)
			if frugalErr := frugalUnmarshal(reader, data, len(buf)); frugalErr == nil {
				return nil
			}
			// Frugal unmarshal failed, reset reader for Apache
			trans = bufiox.NewBytesReader(buf)
		}
	}

	// Fall back to Apache codec
	err := apache.ThriftRead(trans, data)
	if err != nil {
		// use remote.NewTransError to return err back to remote
		// instead of EOF
		return remote.NewTransError(remote.ProtocolError, err)
	}
	return nil
}

