// skipThriftStruct reads and captures a complete Thrift struct from the reader
// Returns the captured bytes for reprocessing by different codecs
func skipThriftStruct(trans bufiox.Reader) ([]byte, error) {
	// Check if we can use netpoll.Reader for efficient skipping
	if nr, ok := trans.(netpoll.Reader); ok {
		decoder := newNetpollSkipDecoder(nr)
		defer decoder.Release()

		n, err := decoder.SkipStruct()
		if err != nil {
			return nil, err
		}

		// Read the captured bytes
		buf, err := nr.Peek(n)
		if err != nil {
			return nil, err
		}

		// Discard the bytes we just peeked
		_ = nr.Discard(n)

		// Return a copy of the buffer
		result := make([]byte, n)
		copy(result, buf)
		return result, nil
	}

	// Fallback: read into a buffer (less efficient)
	// This is a simple implementation that reads the struct
	// For production, you may want a more efficient buffering strategy
	return nil, thrift.NewProtocolException(thrift.NOT_IMPLEMENTED, "skipThriftStruct requires netpoll.Reader")
}

