	var recs []string

	if conn != nil && !conn.IsHealthy {
		recs = append(recs, "Connection unhealthy - check network connectivity and server availability")
	}

	if health != nil && health.ActiveStreams > 100 {
		recs = append(recs, "High number of active streams detected - consider implementing stream pooling or backpressure")
	}

	if errors != nil && errors.TransportErrors > 10 {
		recs = append(recs, "High transport error rate - verify network stability and server capacity")
	}

	if perf != nil && perf.AvgLatency > 1000*time.Millisecond {
		recs = append(recs, "High average latency detected - check server performance and network conditions")
	}

	if len(recs) == 0 {
		recs = append(recs, "All metrics within normal ranges")
	}

	return recs
}

